import * as T from './vendor/three.module.js';
import {poseRoofMantleCarry} from './roof-mantle-equipment.js';
import {createFireEquipment} from './painted-fire-equipment.js';
const V=()=>new T.Vector3(),Q=()=>new T.Quaternion();
// Reuse the approved weapon. Only its right palm is occupied during a low crawl.
export function createCrawlEquipment(worker,profile){
 const gun=worker.weapon,oldGeometry=gun.hose?.geometry,oldUpdate=gun.updateHose,armed=gun.id!=='hands',saved=[gun.root,gun.mount,gun.hose].filter(Boolean).map(o=>({o,p:o.position.clone(),q:o.quaternion.clone(),s:o.scale.clone(),visible:o.visible,frustumCulled:o.frustumCulled})),fire=gun.mount?createFireEquipment(worker,profile):null;
 if(gun.hose)gun.updateHose=()=>{};
 // Roll the long gun onto its side, carried diagonally below the forearm.
 // A straight-ahead upright hold puts the stock through that supporting arm.
 const stocked=!!gun.anchors.stock&&gun.id!=='rpg',gunQ=Q().setFromEuler(new T.Euler(0,stocked?.90:-.06,.035));if(stocked)gunQ.multiply(Q().setFromAxisAngle(new T.Vector3(1,0,0),Math.PI/2));
 let palm=V(),handQ=Q().setFromUnitVectors(new T.Vector3(0,-1,0),new T.Vector3(1,0,0)),grip=V(),wristHeight=.06;
 if(armed){poseRoofMantleCarry(worker,profile);const hand=worker.bones.find(b=>b.name==='hand1');palm=hand.worldToLocal(gun.anchors.grip.getWorldPosition(V()));handQ=gunQ.clone().multiply(stocked?Q().setFromAxisAngle(new T.Vector3(1,0,0),-.55):Q()).multiply(gun.root.getWorldQuaternion(Q()).invert()).multiply(hand.getWorldQuaternion(Q()));grip=gun.root.worldToLocal(gun.anchors.grip.getWorldPosition(V()));let minimum=Infinity;gun.root.updateWorldMatrix(true,true);const inverse=gun.root.matrixWorld.clone().invert();gun.root.traverse(m=>{if(!m.isMesh)return;const p=m.geometry.attributes.position,matrix=inverse.clone().multiply(m.matrixWorld);for(let i=0;i<p.count;i++)minimum=Math.min(minimum,V().fromBufferAttribute(p,i).applyMatrix4(matrix).sub(grip).applyQuaternion(gunQ).y);});wristHeight=Math.max(.06,.018-minimum-palm.clone().applyQuaternion(handQ).y);}
 const segments=18,sides=6,positions=new Float32Array((segments+1)*sides*3),normals=new Float32Array(positions.length),indices=[];let hoseGeometry,disposed=false;
 if(gun.hose){for(let i=0;i<segments;i++)for(let j=0;j<sides;j++){const a=i*sides+j,b=i*sides+(j+1)%sides;indices.push(a,b,a+sides,b,b+sides,a+sides);}hoseGeometry=new T.BufferGeometry();hoseGeometry.setAttribute('position',new T.BufferAttribute(positions,3));hoseGeometry.setAttribute('normal',new T.BufferAttribute(normals,3));hoseGeometry.setIndex(indices);gun.hose.geometry=hoseGeometry;gun.hose.frustumCulled=false;gun.updateHose=()=>{};}
 return {armed,handQ,palm,wristHeight,place(hand){if(!armed){gun.root.visible=false;return;}fire?.reset();worker.root.updateMatrixWorld(true);const point=hand.getWorldPosition(V()).add(palm.clone().applyQuaternion(handQ)).sub(grip.clone().applyQuaternion(gunQ));gun.root.position.copy(worker.root.worldToLocal(point));gun.root.quaternion.copy(worker.root.getWorldQuaternion(Q()).invert().multiply(gunQ));gun.root.visible=true;worker.root.updateMatrixWorld(true);},sync(){if(!gun.hose)return;gun.mount.visible=gun.hose.visible=true;worker.root.updateMatrixWorld(true);const a=worker.root.worldToLocal(gun.anchors.hoseOut.getWorldPosition(V())),b=worker.root.worldToLocal(gun.anchors.hoseIn.getWorldPosition(V())),curve=new T.CatmullRomCurve3([a,a.clone().add(new T.Vector3(-.05,-.12,.07)),b.clone().add(new T.Vector3(-.08,-.12,.08)),b]),point=V(),tangent=V(),side=V(),normal=V(),up=V(),ring=V();for(let i=0;i<=segments;i++){curve.getPoint(i/segments,point);curve.getTangent(i/segments,tangent);up.set(0,Math.abs(tangent.y)>.95?0:1,Math.abs(tangent.y)>.95?1:0);side.crossVectors(tangent,up).normalize();normal.crossVectors(tangent,side).normalize();for(let j=0;j<sides;j++){const angle=j/sides*Math.PI*2;ring.copy(side).multiplyScalar(Math.cos(angle)).addScaledVector(normal,Math.sin(angle));const k=(i*sides+j)*3;positions[k]=point.x+ring.x*.011;positions[k+1]=Math.max(.006,point.y+ring.y*.011);positions[k+2]=point.z+ring.z*.011;normals[k]=ring.x;normals[k+1]=ring.y;normals[k+2]=ring.z;}}hoseGeometry.attributes.position.needsUpdate=hoseGeometry.attributes.normal.needsUpdate=true;},contact(hand){if(!armed)return null;const a=hand.localToWorld(palm.clone()),b=gun.anchors.grip.getWorldPosition(V());return {palm:a.toArray(),grip:b.toArray(),error:a.distanceTo(b)};},dispose(){if(disposed)return;disposed=true;if(hoseGeometry){gun.hose.geometry=oldGeometry;gun.updateHose=oldUpdate;hoseGeometry.dispose();}fire?.restore();for(const {o,p,q,s,visible,frustumCulled}of saved){o.position.copy(p);o.quaternion.copy(q);o.scale.copy(s);o.visible=visible;o.frustumCulled=frustumCulled;}}};
}
